const form=document.getElementById("wallpaperForm"),result=document.getElementById("result");form&&form.addEventListener("submit",e=>{e.preventDefault();const t=parseFloat(document.getElementById("perimeter").value)||0,s=parseFloat(document.getElementById("height").value)||0,l=parseFloat(document.getElementById("rollW").value)||0,n=parseFloat(document.getElementById("rollL").value)||0,r=document.getElementById("pattern").value,o=(parseFloat(document.getElementById("reserve").value)||0)/100;if(t<=0||s<=0||l<=0||n<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Заполните все поля корректными значениями.</p>';return}const c=t*s,i=c*(1+o);let a=n*l;r==="yes"&&(a*=.85);const m=Math.ceil(i/a),p=Math.ceil(c*0);result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Площадь стен</span><span class="val">${fmt(t*s)} м²</span></div>
        <div class="item"><span>Полезная площадь рулона</span><span class="val">${fmt(a)} м²</span></div>
        <div class="item total"><span>Рулонов (с запасом)</span><span class="val">${m} шт.</span></div>
      </div>
      <p class="hint" style="margin-top:14px">С запасом ${fmt(o*100)}%${r==="yes"?", с подгонкой рисунка":""}.</p>
    `});function fmt(e){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(e)}
